import { createRenderContext } from "../../skills/renderer.js";
import {
	installAgentFiles,
	installRuleFiles,
	installSkillFiles,
	removeStaleAgentFiles,
	uninstallAgentFiles,
	uninstallRuleFiles,
	uninstallSkillFiles,
} from "../installer.js";
import { cursorLocationResolver } from "../locations.js";
import type {
	HarnessDescription,
	HarnessInstallContext,
	HarnessInstallResult,
	HarnessPlugin,
	HarnessScope,
	HarnessUninstallContext,
	HarnessUninstallResult,
} from "../types.js";
import ruleTemplate from "./5x-orchestrator.mdc" with { type: "text" };
import permissionsTemplate from "./5x-permissions.mdc" with { type: "text" };
import { listAgentTemplates, renderAgentTemplates } from "./loader.js";
import { listSkillNames, listSkills } from "./skills/loader.js";

const cursorPlugin: HarnessPlugin = {
	name: "cursor",
	description: "Install 5x skills, subagents, and orchestrator rule for Cursor",
	supportedScopes: ["project", "user"],

	locations: cursorLocationResolver,

	describe(scope?: HarnessScope): HarnessDescription {
		const skillNames = listSkillNames();
		const agentNames = listAgentTemplates().map((t) => t.name);

		if (scope === "user") {
			return {
				skillNames,
				agentNames,
				ruleNames: [],
				capabilities: { rules: false },
			};
		}

		return {
			skillNames,
			agentNames,
			ruleNames: ["5x-orchestrator", "5x-permissions"],
			capabilities: { rules: true },
		};
	},

	async install(ctx: HarnessInstallContext): Promise<HarnessInstallResult> {
		const locations = cursorLocationResolver.resolve(
			ctx.scope,
			ctx.projectRoot,
			ctx.homeDir,
		);

		// Resolve skill render context from delegation config
		// authorNative = true when delegationMode is NOT "invoke"
		const authorNative = ctx.config.authorDelegationMode !== "invoke";
		const reviewerNative = ctx.config.reviewerDelegationMode !== "invoke";
		const skillRenderContext = createRenderContext(
			authorNative && reviewerNative, // legacy native flag (both native)
			authorNative,
			reviewerNative,
		);

		const skills = installSkillFiles(
			locations.skillsDir,
			listSkills(skillRenderContext),
			ctx.force,
		);

		// Render and install agent profiles
		// Skip agent templates for roles that use invoke delegation
		const agentTemplates = renderAgentTemplates({
			authorModel: ctx.config.authorModel,
			reviewerModel: ctx.config.reviewerModel,
			authorInvoke: !authorNative,
			reviewerInvoke: !reviewerNative,
		});
		const agents = installAgentFiles(
			locations.agentsDir,
			agentTemplates,
			ctx.force,
		);

		// Remove stale agent files (e.g., when switching from native to invoke mode)
		// Only delete 5x-managed files, preserving user-authored or third-party agents
		const allManagedAgents = listAgentTemplates().map((t) => t.name);
		const staleRemoved = removeStaleAgentFiles(
			locations.agentsDir,
			agentTemplates.map((t) => t.name),
			allManagedAgents,
		);
		// Include stale removals in the result for reporting
		if (staleRemoved.length > 0) {
			agents.removed = staleRemoved;
		}

		if (ctx.scope === "project" && locations.rulesDir) {
			const rules = installRuleFiles(
				locations.rulesDir,
				[
					{ name: "5x-orchestrator", content: ruleTemplate },
					{ name: "5x-permissions", content: permissionsTemplate },
				],
				ctx.force,
			);
			return { skills, agents, rules };
		}

		return {
			skills,
			agents,
			unsupported: { rules: true },
			warnings: [
				"Cursor user rules are settings-managed and not file-backed. Install with --scope project to add the orchestrator rule to your project.",
			],
		};
	},

	async uninstall(
		ctx: HarnessUninstallContext,
	): Promise<HarnessUninstallResult> {
		const locations = this.locations.resolve(
			ctx.scope,
			ctx.projectRoot,
			ctx.homeDir,
		);
		const { skillNames, agentNames, ruleNames } = this.describe(ctx.scope);

		const skills = uninstallSkillFiles(locations.skillsDir, skillNames);
		const agents = uninstallAgentFiles(locations.agentsDir, agentNames);

		if (ctx.scope === "project" && locations.rulesDir && ruleNames?.length) {
			const rules = uninstallRuleFiles(locations.rulesDir, ruleNames);
			return { skills, agents, rules };
		}

		return {
			skills,
			agents,
			unsupported: { rules: true },
		};
	},
};

export default cursorPlugin;

/**
 * Bundled OpenCode harness plugin.
 *
 * Implements the HarnessPlugin contract by wrapping the existing
 * location resolver, agent template renderer, and file installer.
 *
 * This is the default harness — third-party packages can override it
 * by publishing @5x-ai/harness-opencode (or any scoped package) and
 * having it installed in the project.
 */

import { createRenderContext } from "../../skills/renderer.js";
import {
	installAgentFiles,
	installSkillFiles,
	removeStaleAgentFiles,
	uninstallAgentFiles,
	uninstallSkillFiles,
} from "../installer.js";
import { opencodeLocationResolver } from "../locations.js";
import type {
	HarnessDescription,
	HarnessInstallContext,
	HarnessInstallResult,
	HarnessPlugin,
	HarnessScope,
	HarnessUninstallContext,
	HarnessUninstallResult,
} from "../types.js";
import { listAgentTemplates, renderAgentTemplates } from "./loader.js";
import { listSkillNames, listSkills } from "./skills/loader.js";

const opencodePlugin: HarnessPlugin = {
	name: "opencode",
	description: "Install 5x skills and native subagent profiles for OpenCode",
	supportedScopes: ["project", "user"],

	locations: opencodeLocationResolver,

	describe(scope?: HarnessScope): HarnessDescription {
		const skillNames = listSkillNames();
		const agentNames = listAgentTemplates().map((t) => t.name);

		if (scope) {
			return {
				skillNames,
				agentNames,
				ruleNames: [],
				capabilities: { rules: false },
			};
		}

		return { skillNames, agentNames };
	},

	async install(ctx: HarnessInstallContext): Promise<HarnessInstallResult> {
		const locations = opencodeLocationResolver.resolve(
			ctx.scope,
			ctx.projectRoot,
			ctx.homeDir,
		);

		// Resolve skill render context from delegation config
		// authorNative = true when delegationMode is NOT "invoke"
		const authorNative = ctx.config.authorDelegationMode !== "invoke";
		const reviewerNative = ctx.config.reviewerDelegationMode !== "invoke";
		const skillRenderContext = createRenderContext(
			authorNative && reviewerNative, // legacy native flag (both native)
			authorNative,
			reviewerNative,
		);

		// Install skills with the correct render context
		const skills = installSkillFiles(
			locations.skillsDir,
			listSkills(skillRenderContext),
			ctx.force,
		);

		// Render and install agent profiles
		// Skip agent templates for roles that use invoke delegation
		const agentTemplates = renderAgentTemplates({
			authorModel: ctx.config.authorModel,
			reviewerModel: ctx.config.reviewerModel,
			authorInvoke: !authorNative,
			reviewerInvoke: !reviewerNative,
		});
		const agents = installAgentFiles(
			locations.agentsDir,
			agentTemplates,
			ctx.force,
		);

		// Remove stale agent files (e.g., when switching from native to invoke mode)
		// Only delete 5x-managed files, preserving user-authored or third-party agents
		const allManagedAgents = listAgentTemplates().map((t) => t.name);
		const staleRemoved = removeStaleAgentFiles(
			locations.agentsDir,
			agentTemplates.map((t) => t.name),
			allManagedAgents,
		);
		// Include stale removals in the result for reporting
		if (staleRemoved.length > 0) {
			agents.removed = staleRemoved;
		}

		return { skills, agents };
	},

	async uninstall(
		ctx: HarnessUninstallContext,
	): Promise<HarnessUninstallResult> {
		const locations = this.locations.resolve(
			ctx.scope,
			ctx.projectRoot,
			ctx.homeDir,
		);
		const { skillNames, agentNames } = this.describe();

		const skills = uninstallSkillFiles(locations.skillsDir, skillNames);
		const agents = uninstallAgentFiles(locations.agentsDir, agentNames);

		return { skills, agents };
	},
};

export default opencodePlugin;

import {
	listBaseSkillNames,
	renderAllSkillTemplates,
} from "../../skills/loader.js";
import { createRenderContext } from "../../skills/renderer.js";
import { installSkillFiles, uninstallSkillFiles } from "../installer.js";
import { universalLocationResolver } from "../locations.js";
import type {
	HarnessDescription,
	HarnessInstallContext,
	HarnessInstallResult,
	HarnessPlugin,
	HarnessScope,
	HarnessUninstallContext,
	HarnessUninstallResult,
} from "../types.js";

const universalPlugin: HarnessPlugin = {
	name: "universal",
	description:
		"Install 5x skills for any AI coding tool (uses 5x invoke for delegation)",
	supportedScopes: ["project", "user"],

	locations: universalLocationResolver,

	describe(scope?: HarnessScope): HarnessDescription {
		const description: HarnessDescription = {
			skillNames: listBaseSkillNames(),
			agentNames: [],
		};

		if (scope) {
			return {
				...description,
				ruleNames: [],
				capabilities: { rules: false },
			};
		}

		return description;
	},

	async install(ctx: HarnessInstallContext): Promise<HarnessInstallResult> {
		const locations = universalLocationResolver.resolve(
			ctx.scope,
			ctx.projectRoot,
			ctx.homeDir,
		);
		const skills = renderAllSkillTemplates(createRenderContext(false));
		return {
			skills: installSkillFiles(locations.skillsDir, skills, ctx.force),
			agents: { created: [], overwritten: [], skipped: [] },
		};
	},

	async uninstall(
		ctx: HarnessUninstallContext,
	): Promise<HarnessUninstallResult> {
		const locations = universalLocationResolver.resolve(
			ctx.scope,
			ctx.projectRoot,
			ctx.homeDir,
		);
		return {
			skills: uninstallSkillFiles(locations.skillsDir, listBaseSkillNames()),
			agents: { removed: [], notFound: [] },
		};
	},
};

export default universalPlugin;
